  "corpus": {
    "id": "hyperion-operator-public",
    "revision": "2026-08-03",
    "entries": [
      {
        "id": "company-overview",
        "title": "Hyperion Industries",
        "route": "/",
        "visibility": "public",
        "content": "Hyperion Industries builds continuity infrastructure for fragmented operations. Its governed, local-first systems preserve state across people, places, tools, hardware, documents, decisions, and service workflows. Public claims preserve maturity labels and never imply access to private operator systems, records, source code, telemetry, or execution authority."
      },
      {
        "id": "operating-doctrine",
        "title": "Operating doctrine",
        "route": "/alignment",
        "visibility": "public",
        "content": "Hyperion's public doctrine is: facts are source-bound, meaning is context-bound, and actions are authority-bound. Each lane captures state, preserves provenance, exposes context, gates authority, routes approved action, and learns from reality contact. AI may assist, surface, and recommend; a public page cannot borrow private execution authority and the human operator decides."
      },
      {
        "id": "forge",
        "title": "The Forge",
        "route": "/forge",
        "visibility": "public",
        "content": "The Forge is an inquiry-led lane for custom PCs, simulation rigs, local AI boxes, upgrades, and deployment-ready workstations. The public Forge Concierge guides visitors one question at a time through workload, room, budget, service, and tradeoff posture, then holds the resulting brief for human review. Its product neighborhoods and counterfactual previews are not quotes, compatibility verdicts, inventory promises, configurations, or orders."
      },
      {
        "id": "card-studio",
        "title": "Hyperion Card Studio",
        "route": "/card-studio",
        "visibility": "public",
        "content": "Hyperion Card Studio covers digital identity cards and physical NFC cards. The digital card is free. Public catalog posture lists PVC cards from $39, metal cards from $89, Pro at $9 per month or $90 per year, and Team pricing as custom. Payment and fulfillment remain operator-reviewed through draft invoices; there is no public cart or checkout on the Hyperion site."
      },
      {
        "id": "systems-posture",
        "title": "Public systems posture",
        "route": "/systems",
        "visibility": "public",
        "content": "CHR0N.OS is the public stable-beta lane for classification, provenance, lineage, recovery, and temporal context under operator custody. Mnem.OS is in development as a continuity layer for snapshots, histories, recovery, and long-horizon context under owner control. Kosm.OS, Log.OS, Synth.OS, Eid.OS, Eth.OS, and Myth.OS are architecture, concept, or research lanes and must not be described as shipped products."
      },
      {
        "id": "contact-and-intake",
        "title": "Contact and intake",
        "route": "/contact",
        "visibility": "public",
        "content": "Hyperion begins with a bounded assessment of the continuity failure, workload, trust surface, support issue, or relationship question. Visitors should share the current environment, affected people or systems, known evidence, constraints, and what a useful first artifact would be. A submitted signal begins operator review; it is not a quote, contract, deployment, access grant, or automation promise. Visitors must not submit credentials, secrets, private archives, restricted logs, or sensitive operational records."
      },
      {
        "id": "founding-operators",
        "title": "Founding operators",
        "route": "/founders",
        "visibility": "public",
        "content": "Victor Amani is the founder and systems architect behind Hyperion Industries' local-first infrastructure direction. Keshawn Rowe is the founding operator focused on operations, deployment, field systems, build intake, and client handoff. Public profiles describe responsibility without exposing private records or operator controls."
      }
    ]
  },
  "sha256": "f256f5fe52cb0b07326a9ff4888c6a205c0cc5d929aab67cfdad1349e92ed493"
